// Gas metering: sum the cost of each operation
const ops=["SLOAD", "ADD", "SSTORE"];
const gas={SSTORE:20000,SLOAD:2100,ADD:3,MUL:5,CALL:700,LOG:375};
const total=ops.reduce((a,o)=>a+(gas[o]||0),0);
console.log('ops:',ops.join(','),'| gas used:',total);

